// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    keepMyEther c;
    Recorder rec;

    function setUp() public {
        c = new keepMyEther();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1e30);
        vm.deal(address(rec), amount);

        // deposit via fallback from the recorder
        vm.prank(address(rec));
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);

        // withdraw back to the recorder
        vm.prank(address(rec));
        c.withdraw();

        // general rule: C sends out exactly the recorded balance, exactly once,
        // and ends holding nothing.
        assertTrue(
            rec.received() == amount && rec.calls() == 1 && address(c).balance == 0 && c.balances(address(rec)) == 0
        );
    }
}

contract Recorder {
    uint256 public received;
    uint256 public calls;

    fallback() external payable {
        if (msg.sig == 0x00000000) {
            // deposit into C's fallback: just accept (and pay) ether
        }
        // record only the ether C sends us during withdraw (non-empty context):
        // our deposit is made via a low-level call with empty data too, so
        // accumulate by source: only count when called from C during withdraw.
        // Simplify: record value received from C at any time; the deposit goes
        // from us to C, not from C to us, so this is safe.
        received += msg.value;
        calls += 1;
    }

    receive() external payable {
        received += msg.value;
        calls += 1;
    }
}
